-- Re-enable triggers
SET session_replication_role = 'origin';

-- Recalculate task points if needed
DO \$\$
BEGIN
  -- Update tasks with calculated points based on difficulty and time_required weights
  UPDATE tasks
  SET points = ROUND(
    (
      COALESCE(
        (SELECT weight FROM task_parameters WHERE parameter_type = 'difficulty' AND value = tasks.difficulty::text LIMIT 1),
        1.0
      ) *
      COALESCE(
        (SELECT weight FROM task_parameters WHERE parameter_type = 'time_required' AND value = tasks.time_required::text LIMIT 1),
        1.0
      ) *
      COALESCE(
        (SELECT config_value::numeric FROM system_config WHERE config_key = 'points_calculation_factor' LIMIT 1),
        2.5
      )
    )::numeric, 0
  )
  WHERE difficulty IS NOT NULL AND time_required IS NOT NULL;
END \$\$;